(1, '10 Game Rookie', 'You\'ve played 10 games of PourQuestions, how\'s that liver of yours doing?', '/img/achievements/10gamerookie.jpg', 'games_played', 10, 0, NULL, NULL, NULL, '2026-04-01 12:48:38', '2026-04-01 12:48:38'),
(2, '50 Game Veteran', '50 games, you have a drinking problem!', '/img/achievements/50gameveteran.jpg', 'games_played', 50, 0, NULL, NULL, NULL, '2026-04-01 12:52:50', '2026-04-01 12:52:50'),
(3, 'DryHarry', 'How did you even do this?! An Entire Game?! Without shots?!! HOW?!?!?', '/img/achievements/dryharry.jpg', 'single_game_shots', 0, 1, NULL, NULL, NULL, '2026-04-01 13:14:10', '2026-04-01 16:28:12'),
(4, 'Founder', 'You are one of the first 100 players, here\'s a little badge as a thank you.', '/img/achievements/founder.jpg', 'member_number', 100, 0, NULL, NULL, NULL, '2026-04-01 13:15:29', '2026-04-01 16:24:31'),
(5, 'Shotbinger', '1000 shots in total, we sincerely hope that you didnt actually drink all of those.', '/img/achievements/shotbinger.jpg', 'total_shots', 1000, 0, NULL, NULL, NULL, '2026-04-01 13:18:58', '2026-04-01 13:18:58');
