INSERT INTO `modifiers` (`id`, `name`, `description`, `icon`, `turnbased`, `effects`, `coupled_gamepack_id`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'High Tolerance', 'Those shots? You can take more. Everytime you have to take 1 shot, take 2 instead.', '1759008843_booze.svg', 1, '\"{\\r\\n    \\\"onShot\\\": {\\r\\n        \\\"multiplier\\\": 2\\r\\n    },\\r\\n    \\\"turnsAffected\\\": {\\r\\n        \\\"turns\\\": 3\\r\\n    }\\r\\n}\"', NULL, 1, '2025-09-23 08:56:35', '2025-09-28 06:18:56'),
(2, 'Low Tolerance', 'You clearly can\'t handle this. Skip the next shot you would have to take.', '1759008837_glass-shot.svg', 0, '\"{\\r\\n  \\\"onShot\\\": {\\r\\n    \\\"skip\\\": 1,\\r\\n    \\\"consume\\\": true\\r\\n  }, \\r\\n    \\\"turnsAffected\\\": {\\r\\n        \\\"turns\\\": 1\\r\\n    }\\r\\n}\"', NULL, 1, '2025-09-23 10:26:54', '2025-09-28 06:19:19'),
(3, 'Trickster', 'Your cunning skills will be the end of your friends. The next time you answer a question incorrectly, the shot passes on to any of the other players.', '1759046573_card-joker.svg', 0, '\"{\\r\\n  \\\"onWrongAnswer\\\": {\\r\\n    \\\"redirect_shot\\\": \\\"random\\\",\\r\\n    \\\"consume\\\": true\\r\\n  }\\r\\n}\"', NULL, 1, '2025-09-28 06:03:27', '2025-09-28 06:03:27'),
(4, 'No Pressure', 'The next question you have to answer, everyone drinks if you get it wrong. We can\'t guarantee safety from your friends if that happens.', '1759009088_duality.svg', 1, '\"{\\r\\n  \\\"onWrongAnswer\\\": {\\r\\n    \\\"everyone_drinks\\\": true,\\r\\n    \\\"consume\\\": true\\r\\n  }\\r\\n}\"', NULL, 1, '2025-09-28 06:04:23', '2025-09-28 06:04:23'),
(5, 'Frienemies', '\"$player1 and $player2 are now frienemies! Whenever one of them answers correctly, the other player has to drink.\"', '1759009081_face-to-face.svg', 0, '\"{\\r\\n  \\\"onCorrectAnswer\\\": {\\r\\n    \\\"frienemy_drinks\\\": true\\r\\n  },\\r\\n  \\\"data\\\": {\\r\\n    \\\"frienemy_id\\\": null\\r\\n\\r\\n  }, \\r\\n  \\\"specialEffect\\\": {\\r\\n   \\\"brokenOnRedistribute\\\":1\\r\\n   }\\r\\n}\"', NULL, 1, '2025-09-28 06:06:43', '2025-09-28 06:21:11'),
(6, 'Drinking Buddies', '\"$player1 and $player2 are now drinking buddies! If one of them has to take a shot, the other shares the same fate.\"', '1759009075_lovers.svg', 0, '\"{\\r\\n  \\\"onShot\\\": {\\r\\n    \\\"buddy_drinks_too\\\": true\\r\\n  },\\r\\n  \\\"data\\\": {\\r\\n    \\\"buddy_id\\\": null\\r\\n  }, \\r\\n  \\\"specialEffect\\\": {\\r\\n   \\\"brokenOnRedistribute\\\":1\\r\\n   }\\r\\n}\"', NULL, 1, '2025-09-28 06:07:34', '2025-09-28 06:21:30'),
(7, 'Murderer', 'You murdered another player. If they come back to haunt you and answer correctly, you’ll have to drink as revenge.', '1759046979_jason-mask.svg', 1, '\"{\\r\\n  \\\"role\\\": \\\"murderer\\\",\\r\\n  \\\"onKill\\\": {\\r\\n    \\\"assign_dead\\\": true\\r\\n  },\\r\\n  \\\"onHaunted\\\": {\\r\\n    \\\"take_shot\\\": true\\r\\n  }\\r\\n}\"', NULL, 1, '2025-09-28 06:13:45', '2025-09-28 06:14:38'),
(8, 'Dead', 'You have been murdered! Take a shot immediately. If you answer your next question correctly, your murderer will have to drink as revenge.', '1759046982_dead-head.svg', 1, '\"{\\r\\n  \\\"role\\\": \\\"dead\\\",\\r\\n  \\\"onAcquire\\\": {\\r\\n    \\\"take_shot\\\": true\\r\\n  },\\r\\n  \\\"onCorrectAnswer\\\": {\\r\\n    \\\"haunt_murderer\\\": true\\r\\n  }\\r\\n}\"', NULL, 1, '2025-09-28 06:14:33', '2025-09-28 06:14:33');
